    /* ---------------- LASIK bulk sign-off ----------------

       The LASIK chart is stored as one row per phase - TypeId 1 Pre-Op,
       2 Intra-Op, 3 Post-Op - so the Nurse list carries one line per phase and
       each one opens its own tab in the quick summary's LASIK template.

       MOCK: the appointment list service does not return per-phase LASIK
       sign-off status yet. The two mocked fields in SeedLasikSignOffState are
       stand-ins so the checkboxes can be exercised - point them at the real
       fields when the API returns them; nothing else here has to change. */
    /* A LASIK chart is nurse / ASC-technician work, so only those two roles sign
       its phases. */
    $scope.LasikSignOffRoles = [8, 38];

    $scope.IsLasikSignOffRole = function () {
        return $scope.LasikSignOffRoles.indexOf(Number($scope.RoleId)) !== -1;
    };

    /* The two categories charted in this template are named differently on screen:
       3 is LASIK, 4 is the Laser (Yag, Retina) chart. The phase rows, the popover
       and the summary tab all take their wording from here so the two never drift
       apart. An appointment with neither category reads as LASIK, which is what
       every one of these labels said before. */
    $scope.GetLasikWord = function (item) {
        return (Number((item || {}).LasikSurgeryCategoryId) === 4) ? "Laser" : "Lasik";
    };

    $scope.GetLasikTemplateName = function (item) {
        return (Number((item || {}).LasikSurgeryCategoryId) === 4)
            ? "Laser (Yag, Retina)"
            : "Lasik Template";
    };

    $scope.LasikSignOffPhases = [
        { "Key": "PreOp", "TypeId": 1, "TypeName": "Pre-Op", "Type": 12, "Title": "Pre-Op LASIK", "Screen": "LasikPreop", "Model": "NursePreOpLasik", "Status": "LasikPreopChartStatus", "HasData": "IsLasikPreopData", "SignOff": "LasikPreOpSignOffInfo" },
        { "Key": "IntraOp", "TypeId": 2, "TypeName": "Intra-Op", "Type": 13, "Title": "Intra-Op LASIK", "Screen": "LasikIntraop", "Model": "NurseIntraOpLasik", "Status": "LasikIntraopChartStatus", "HasData": "IsLasikIntraopData", "SignOff": "LasikIntraOpSignOffInfo" },
        { "Key": "PostOp", "TypeId": 3, "TypeName": "Post-Op", "Type": 14, "Title": "Post-Op LASIK", "Screen": "LasikPostop", "Model": "NursePostOpLasik", "Status": "LasikPostopChartStatus", "HasData": "IsLasikPostopData", "SignOff": "LasikPostOpSignOffInfo" }
    ];

    /* The signing-status popover has one template per chart kind - LASIK reports
       three phases, everything else keeps the four Pre/Intra/Recovery columns.
       The quotes are part of the value: uib-popover-template evaluates it. */
    $scope.GetSignOffStatusPopoverTemplate = function (item) {
        return (item && item.IsLasikTemplate)
            ? "'auditReportLasikSingningStatus.html'"
            : "'auditReportSingningStatus.html'";
    };

    $scope.SeedLasikSignOffState = function (appointment) {
        if (!appointment) { return appointment; }

        appointment.SurgeryList = appointment.SurgeryList || [];
        appointment.LasikLastSignOffUserDetails = appointment.LasikLastSignOffUserDetails || [];

        /* This appointment's surgery category, taken from this appointment's own
           surgery.

           SurgeryList comes back holding every surgery in the response, not just
           this patient's - each row names the appointment it belongs to, so the
           rows are matched on that first. Reading SurgeryList[0] took whichever
           surgery happened to be first, which is why every patient came out as
           the same category. */
        var appointmentId = Number(appointment.AppointmentID || appointment.AppointmentId) || 0;
        var namesAnAppointment = false;
        var ownSurgeries = [];

        angular.forEach(appointment.SurgeryList, function (surgery) {
            var surgeryAppointmentId = Number((surgery || {}).AppointmentId || (surgery || {}).AppointmentID) || 0;

            if (surgeryAppointmentId !== 0) { namesAnAppointment = true; }
            if (surgeryAppointmentId !== 0 && surgeryAppointmentId === appointmentId) {
                ownSurgeries.push(surgery);
            }
        });

        /* No row named an appointment at all - nothing to match on, so the list is
           read as it stands, exactly as before. When the rows DO name one and none
           is this appointment's, this appointment has no surgery of its own and
           keeps its Nurse and Anesthesia rows. */
        if (!namesAnAppointment) { ownSurgeries = appointment.SurgeryList; }

        /* This appointment's own surgeries, kept on the appointment so the summary
           screen can be given them instead of the whole response. The summary reads
           SurgeryList[0] to decide which template to show, so handing it the
           unfiltered list showed another patient's template. */
        appointment.OwnSurgeryList = ownSurgeries;

        var surgeryCategoryId = 0;

        angular.forEach(ownSurgeries, function (surgery) {
            if (surgeryCategoryId === 0) {
                surgeryCategoryId = Number((surgery || {}).SurgeryCategoryId) || 0;
            }
        });

        /* SurgeryCategoryId 3 (LASIK) and 4 (Laser / YAG) are charted in the LASIK
           template. Every other category, and an appointment that states none, is
           charted in the Pre-Op / Intra-Op / Recovery notes as it always was. */
        appointment.IsLasikTemplate = (surgeryCategoryId === 3 || surgeryCategoryId === 4);
        /* the LASIK template popup is resolved with the surgery's own category */
        /* the surgery's own category, carried through to the LASIK template popup.
           Left as it actually is - 0 when the surgery names none - rather than
           defaulted to 3, which made every appointment look like a LASIK one when
           the object was inspected. The two places that read it already fall back
           to 3 themselves. */
        appointment.LasikSurgeryCategoryId = surgeryCategoryId;
        /* The signing-status popover is compiled in its own scope and cannot reach
           the controller, but it is handed the appointment as popoverData - so the
           word it names the phases with travels on the appointment itself. */
        appointment.LasikWord = (surgeryCategoryId === 4) ? "Laser" : "LASIK";

        /* LASIK (3) and YAG (4) are done without anesthesia, so there is no
           anesthesia chart to sign on them - the whole Anesthesia group is left
           off the sign-off list. An appointment with no surgery on it keeps the
           anesthesia group, which is what every chart did before. */
        appointment.IsAnesthesiaSignOffRequired = !appointment.SurgeryList.some(function (surgery) {
            var categoryId = Number((surgery || {}).SurgeryCategoryId);
            return categoryId === 3 || categoryId === 4;
        });

        /* The sign-off rows arrive as one list for the whole chart, each row naming
           its phase by TypeId - 1 Pre-Op, 2 Intra-Op, 3 Post-Op. A row belongs to
           exactly one phase, so it is never shown under two of them. A row with no
           TypeId is placed by the screen it was signed from, and if it carries
           neither it is not shown at all - showing it everywhere is what produced
           the duplicated signers. */
        var signOffRows = appointment.LasikLastSignOffUserDetails;

        /* "Lasik-PreOp", "LasikPreop", "Pre-Op", "preop" all name the same phase,
           so names are compared with the punctuation and case taken out. */
        var normalize = function (value) {
            return String(value === undefined || value === null ? "" : value)
                .toLowerCase().replace(/[^a-z0-9]/g, "");
        };

        /* Read a field without caring how it is cased - this codebase spells
           TypeId, TypeID and DoctorID all three ways, and one wrong guess here
           reads undefined and drops the row. */
        var pick = function (row, fieldNames) {
            var wanted = fieldNames.map(normalize);
            var found;

            angular.forEach(row, function (value, key) {
                if (found !== undefined) { return; }
                if (wanted.indexOf(normalize(key)) !== -1 &&
                    value !== null && value !== undefined && value !== '') {
                    found = value;
                }
            });
            return found;
        };

        var rowBelongsToPhase = function (row, phase) {
            row = row || {};

            /* a numeric TypeId settles it outright */
            var rawTypeId = pick(row, ["TypeId", "LasikTypeId", "PhaseId"]);
            var typeId = Number(rawTypeId);
            if (rawTypeId !== undefined && !isNaN(typeId)) {
                return typeId === phase.TypeId;
            }

            /* no usable TypeId - fall back to whatever names the phase. A row that
               names nothing belongs to no phase, so it is never shown twice. */
            var names = [phase.Screen, phase.TypeName, phase.Key, "lasik" + phase.Key]
                .map(normalize);

            var candidate = normalize(pick(row, ["TypeName", "ScreenType", "Screen", "ScreenName", "TypeId"]));
            return candidate !== "" && names.indexOf(candidate) !== -1;
        };

        /* one shape for the popover, whatever the service called the fields */
        var toSignOffRow = function (row) {
            row = row || {};
            return {
                "SignOffUserName": pick(row, ["SignOffUserName", "UserFullName", "FullName", "SignOffUser", "SignedBy"]) || '',
                "SuffixName": pick(row, ["SuffixName", "Suffix"]) || '',
                "LicenseNumber": pick(row, ["LicenseNumber", "LicenseNo"]) || '',
                "Date": pick(row, ["Date", "SignOffDate", "SignedOffDate", "ReviewedByDateTime", "SignOffDateTime"]) || null
            };
        };

        var matchedRowCount = 0;

        angular.forEach($scope.LasikSignOffPhases, function (phase) {
            appointment[phase.Status] = appointment[phase.Status] || "";
            /* nothing saved for the phase -> nothing to sign, so the box stays
               disabled, exactly as IsPreopData / IsIntraopData work above */
            appointment[phase.HasData] = appointment[phase.HasData] || false;
            /* This line used to read:
                   if (appointment[phase.Status] !== "") { IsLasikTemplate = true; }
               It ran for every appointment, so any chart carrying a LASIK phase
               status had the flag forced on whatever its surgery category was.
               The category above decides it now. */

            appointment[phase.SignOff] = signOffRows.filter(function (row) {
                return rowBelongsToPhase(row, phase);
            }).map(toSignOffRow);

            matchedRowCount += appointment[phase.SignOff].length;

            /* a phase already signed shows as a ticked, disabled box */
            appointment[phase.Model] = (appointment[phase.Status] === "E");
        });

        /* The service returns one sign-off list for the whole LASIK chart and its
           rows do not always name the phase they were signed from - the LASIK chart
           popup itself copies the same list onto all three phase rows. When no row
           named a phase, read the list as it stands so a signed phase still shows
           its signer, date and time; rows repeated verbatim are collapsed so a
           column names each signer once. */
        if (signOffRows.length > 0 && matchedRowCount === 0) {
            var fallbackRows = [];
            var seenSigners = {};

            angular.forEach(signOffRows, function (row) {
                var signOff = toSignOffRow(row);
                var key = signOff.SignOffUserName + '|' + signOff.Date;

                if (seenSigners[key]) { return; }
                seenSigners[key] = true;
                fallbackRows.push(signOff);
            });

            angular.forEach($scope.LasikSignOffPhases, function (phase) {
                appointment[phase.SignOff] = angular.copy(fallbackRows);
            });
        }

        /* kept for the older name used elsewhere in the list markup */
        appointment.IsLasikSurgery = appointment.IsLasikTemplate;

        return appointment;
    };

