    $scope.NavToAscchart = function () {
        if ($scope.selectedPatientobj.AppointmentStatusId === 7 || $scope.selectedPatientobj.AppointmentStatusId === 5 || $scope.selectedPatientobj.AppointmentStatusId === 6) {
            alertify.error("Appointment Cancelled!");
            return;
        }

        if ($scope.selectedPatientobj.AppointmentStatusId === 8 || $scope.selectedPatientobj.AppointmentStatusId === 9 || $scope.selectedPatientobj.AppointmentStatusId === 10) {
            alertify.error("Appointment Rescheduled!");
            return;
        }
        if ($scope.selectedPatientobj.CheckinStatusId === 1) {
            alertify.error("Patient has not checkedin yet!");
            return;
        }

        if ($scope.selectedPatientobj.AdmissionId == 0) {
            alertify.error("Patient is not admitted");
            return;
        }

        /* A LASIK chart is written in the LASIK template, not the Pre/Intra/Post
           chart, so Edit opens that instead. Every other patient keeps the
           existing route. */
        var selectedAppt = $filter('filter')($scope.AscAppointmentsList,
            { 'AppointmentID': $scope.selectedPatientobj.AppointmentID }, true)[0] || {};

        if (selectedAppt.IsLasikTemplate) {
            $uibModalInstance.close();

            $uibModal.open({
                "templateUrl": "templates/uibpopups/navtoLasikTempPopup.html",
                "controller": "USLasikTempPopupCtrl",
                "backdrop": "static",
                "keyboard": false,
                "resolve": {
                    "SurgeryCategoryId": function () { return selectedAppt.LasikSurgeryCategoryId || 3; },
                    "allUserList": function () { return $scope.allUserList; },
                    "cacheStorageItem": function () { return $scope.cacheStorageItem; }
                },
                "windowClass": "modal__popup--1 bottom-to-top-modal"
            });
            return;
        }

        if ($scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 1) {
            if ($scope.PreopNurseAnestiatab == 1 || $scope.PreopNurseAnestiatab == 2) {
                var sObj = {
                    "Tab": "PreOp",
                };
                sObj.Type = $scope.PreopNurseAnestiatab == 2 ? "bulksignoff" : "";
                if (($scope.PreopNurseAnestiatab != 2) && ($scope.RoleId == 25 || $scope.RoleId == 30)) {
                    sObj.Type = "navbulksignoff";
                }
            }
            if ($scope.PreopNurseAnestiatab == 3) {
                var type = 1;
                var screentype = "ASC";
            }
        } else if ($scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 2) {
            var sObj = {
                "Tab": "IntraOp",
            };
            sObj.Type = $scope.IntropNurseAnestiatab == 2 ? "bulksignoff" : "";
            if (($scope.IntropNurseAnestiatab != 2) && ($scope.RoleId == 25 || $scope.RoleId == 30)) {
                sObj.Type = "navbulksignoff";
            }
        } else if ($scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 3) {
            var sObj = {
                "Tab": "PostOp",
            };
            sObj.Type = $scope.PostopNurseAnestiatab == 2 ? "bulksignoff" : "";
            if (($scope.PostopNurseAnestiatab != 2) && ($scope.RoleId == 25 || $scope.RoleId == 30)) {
                sObj.Type = "navbulksignoff";
            }
        } else if ($scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 4) {
            var type = 3;
            var screentype = "ASC";
        } else if ($scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 5) {
            var type = 2;
            var screentype = "ASC";
        } else {
            var sObj = {
                "Tab": "PreOp",
            };
        }
        eHnoteMasterDataService.addSelectedSurgeryOperationobj(sObj);
        $uibModalInstance.close();
        if ($scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 5 || $scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 4 || ($scope.AscActiveTabsObj.IsPreIntraPostActiveTab == 1 && $scope.PreopNurseAnestiatab == 3)) {
            let mInstanceAdd = $uibModal.open({
                "templateUrl": "templates/uibpopups/faceLiftPopup.html",
                "controller": "USFaceSheetPopupCtrl",
                "backdrop": "static",
                "keyboard": false,
                "windowClass": "offcanves-right  ",
                "resolve": {
                    "allUserList": function () { return $scope.allUserList; },
                    "SubTab": function () { return type; },
                    "ScreenType": function () { return screentype; },
                    "ParentObj": function () { return $scope.ParentObj; },
                }
            });
        }
        else {
            $location.url("/profile");
        }
    }
