    $scope.SelectPatientallsignoff = function (item) {
        console.log($scope.AscAppointmentsList);
        angular.forEach($scope.AscAppointmentsList, function (as) {
            if (as.AppointmentID == item.AppointmentID) {
                as.Allsignoffs = as.Allsignoffs
            } else {
                as.Allsignoffs = false;
            }
        })
        // $scope.AscAppointmentsList.forEach(aitem => aitem.Allsignoffs = false);
        $scope.AllChartsignoffs = item.Allsignoffs||false;
        item.Allsignoffs = item.Allsignoffs;
        if (item.Allsignoffs) {
            /* objmanage = [];*/

            /* A LASIK chart shows its three phases in place of the four standard
               nurse rows, so Select all ticks those instead - and a nurse or an
               ASC technician can both do it. A phase already signed stays as it
               is; there is nothing left to sign on it. */
            if (item.IsLasikTemplate && $scope.IsLasikSignOffRole()) {
                angular.forEach($scope.LasikSignOffPhases, function (phase) {
                    item[phase.Model] = (item[phase.Status] == 'E' || item[phase.HasData]) ? true : false;
                });
            }

            /* the four standard nurse rows are hidden on a LASIK chart, so they
               are not ticked behind the user's back */
            if ($scope.RoleId == 8 && !item.IsLasikTemplate) {  //nurse
                $scope.checkedchecklistcount = 0;
                $scope.overallchecklistcount = 0;
                item.IsPreopData == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount; item.IsIntraopData == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount; item.IsPostopData == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount;
                $scope.overallchecklistcount = angular.copy($scope.checkedchecklistcount);
                item.NursePreop = false;
                if (item.PreOpNurseChartStatus == 'E' || item.IsPreopData) {
                    item.NursePreop = true;
                    //objmanage.push({ 'NursePreop': true });
                }
                item.NurseIntraop = false;
                if (item.IntraOpNurseChartStatus == 'E' || item.IsIntraopData) {
                    item.NurseIntraop = true;
                    //objmanage.push({ 'NurseIntraop': true });
                }
                item.NursePostop = false;
                if (item.PostOpNurseChartStatus == 'E' || item.IsPostopData) {
                    item.NursePostop = true;
                    //objmanage.push({ 'NursePostop': true });
                }
                item.NursePostopR2 = false;
                if (item.R2PostOpNurseChartStatus == 'E' || item.IsPostopData) {
                    item.NursePostopR2 = true;
                }

                item.DischareSummary = false;
                if (item.DischargeChartStatus == 'E' || item.IsDischargeData) {
                    item.DischareSummary = true;
                    //objmanage['DischareSummary'] = (item.IsDischargeData) ? true : false;
                }
                item.DoctorNotes = false;
                if (item.FaceSheetChartStatus == 'E' || item.IsfaceSheetData) {
                    item.DoctorNotes = true;
                    //objmanage['DischareSummary'] = (item.IsDischargeData) ? true : false;
                }
            }
            /* the anesthesia group is not on screen for a LASIK or YAG surgery, so
               Select all does not tick it behind the user's back */
            if (($scope.RoleId == 25 || $scope.RoleId == 30) && item.IsAnesthesiaSignOffRequired) { // anestieast
                $scope.checkedchecklistcount = 0;
                $scope.overallchecklistcount = 0;
                item.IsPreopData == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount; item.IsIntraopData == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount; item.IsPostopData == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount;
                $scope.overallchecklistcount = angular.copy($scope.checkedchecklistcount);
                item.AnesthesiaPreop = false;
                if (item.PreOpAnesthesiaChartStatus == 'E' || item.IsPreopData) {
                    item.AnesthesiaPreop = true;
                }
                item.AnesthesiaIntraop = false;
                if (item.IntraOpAnesthesiaChartStatus == 'E' || item.IsIntraopData) {
                    item.AnesthesiaIntraop = true;
                }
                item.AnesthesiaPostop = false;
                if (item.PostOpAnesthesiaChartStatus == 'E' || item.IsPostopData) {
                    item.AnesthesiaPostop = true;
                }

                item.AnesthesiaPostopR2 = false;
                if (item.R2PostOpAnesthesiaChartStatus == 'E' || item.IsPostopData) {
                    item.AnesthesiaPostopR2 = true;
                }
            }
            if (($scope.RoleId == 43 || $scope.RoleId == 1) ) {
                $scope.checkedchecklistcount = 0;
                $scope.overallchecklistcount = 0;
                item.DoctorNotes == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount; item.DoctorNotes == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount; item.DischareSummary == false ? $scope.checkedchecklistcount++ : $scope.checkedchecklistcount;
                $scope.overallchecklistcount = angular.copy($scope.checkedchecklistcount);
                item.DoctorNotes = false;
                if (item.FaceSheetChartStatus == 'E' || item.IsfaceSheetData) {
                    item.DoctorNotes = true;
                    //objmanage['DoctorNotes'] = (item.IsfaceSheetData) ? true : false;
                }
                item.OperativeNotes = false;
                if (item.OperativeChartStatus == 'E' || item.IsOperativeData) {
                    item.OperativeNotes = true;
                    //objmanage['OperativeNotes'] = (item.IsOperativeData) ? true : false;
                }
                item.DischareSummary = false;
                if (item.DischargeChartStatus == 'E' || item.IsDischargeData) {
                    item.DischareSummary = true;
                    //objmanage['DischareSummary'] = (item.IsDischargeData) ? true : false;
                }
            }
            //item.NursePreop = true;
            //item.NurseIntraop = true;
            //item.NursePostop = true;
            //item.AnesthesiaPreop = true;
            //item.AnesthesiaIntraop = true;
            //item.AnesthesiaPostop = true;
        }
        else {
            item.NursePreop = false
            item.NurseIntraop = false
            item.NursePostop = false
            item.AnesthesiaPreop = false
            item.AnesthesiaIntraop = false
            item.AnesthesiaPostop = false
            item.AnesthesiaPostopR2=false
            item.DoctorNotes = false
            item.OperativeNotes = false
            item.DischareSummary = false
            if (($scope.RoleId == 43 || $scope.RoleId == 1) ) {
                item.DoctorNotes = (item.FaceSheetChartStatus === 'E') ? true : false;
                item.OperativeNotes = (item.OperativeChartStatus === 'E') ? true : false;
                item.DischareSummary = (item.DischargeChartStatus === 'E') ? true : false;
            }
            if ($scope.RoleId == 8) {
                item.NursePreop = (item.PreOpNurseChartStatus === 'E') ? true : false;
                item.NurseIntraop = (item.IntraOpNurseChartStatus === 'E') ? true : false;
                item.NursePostop = (item.PostOpNurseChartStatus === 'E') ? true : false;
                item.NursePostopR2 = (item.R2PostOpNurseChartStatus === 'E') ? true : false;
            }

            /* clearing Select all leaves the already-signed phases ticked */
            angular.forEach($scope.LasikSignOffPhases, function (phase) {
                item[phase.Model] = (item[phase.Status] === 'E') ? true : false;
            });
            if ($scope.RoleId == 8) {
                item.AnesthesiaPreop = (item.PreOpAnesthesiaChartStatus === 'E') ? true : false;
                item.AnesthesiaIntraop = (item.IntraOpAnesthesiaChartStatus === 'E') ? true : false;
                item.AnesthesiaPostop = (item.PostOpAnesthesiaChartStatus === 'E') ? true : false;
                item.AnesthesiaPostopR2 = (item.R2PostOpAnesthesiaChartStatus === 'E') ? true : false;
            }
        }
        reformAppointmentConsentsandOrgConsents($scope.consentsMainObj.SelectedConsentTemplateId);
    }
    $scope.ChangeIsConsentFormNurseSign = function (IsConsentFormNurseSign) {
        $scope.IsConsentFormNurseSign = IsConsentFormNurseSign || false;


    }
    $scope.ChangeIsConsentFormAnesthesiaSign = function (IsConsentFormAnesthesiaSign) {
        $scope.IsConsentFormAnesthesiaSign = IsConsentFormAnesthesiaSign || false;


    }
    $scope.ChangeConsentFormDctorSign = function (IsConsentFormDctorSign) {
        $scope.IsConsentFormDctorSign = IsConsentFormDctorSign || false;


    }
    $scope.bulksignoff = function (TabNo) {
        if (TabNo == 1) {
            $scope.allUserList = $scope.allUserList || [];
            let AppointmentID = $scope.selectedPatientobj.AppointmentID || 0;
            $scope.AscAppointmentsList1 = $filter('filter')($scope.AscAppointmentsList, { 'AppointmentID': AppointmentID }, true) || [];
            var seletedPatientInfo = [];
            if ($scope.AscAppointmentsList1.length > 0) {
                seletedPatientInfo = $filter('filter')($scope.AscAppointmentsList1, function (item) {
                    return item.Allsignoffs === true ||
                        item.NursePreop === true ||
                        item.NurseIntraop === true ||
                        item.NursePostop === true ||
                        item.AnesthesiaPreop === true ||
                        item.AnesthesiaIntraop === true ||
                        item.AnesthesiaPostop === true ||
                        item.DoctorNotes == true ||
                        item.OperativeNotes == true ||
                        item.DischareSummary == true ||
                        item.AnesthesiaPostopR2 == true ||
                        item.NursePostopR2 == true ||
                        item.NursePreOpLasik === true ||
                        item.NurseIntraOpLasik === true ||
                        item.NursePostOpLasik === true
                }) || [];
            }
            else {
                seletedPatientInfo = $filter('filter')($scope.AscAppointmentsList, function (item) {
                    return item.Allsignoffs === true ||
                        item.NursePreop === true ||
                        item.NurseIntraop === true ||
                        item.NursePostop === true ||
                        item.AnesthesiaPreop === true ||
                        item.AnesthesiaIntraop === true ||
                        item.AnesthesiaPostop === true ||
                        item.DoctorNotes == true ||
                        item.OperativeNotes == true ||
                        item.DischareSummary == true ||
                        item.AnesthesiaPostopR2 == true ||
                        item.NursePostopR2 == true ||
                        item.NursePreOpLasik === true ||
                        item.NurseIntraOpLasik === true ||
                        item.NursePostOpLasik === true
                }) || [];
            }
            let Consentsignneed = $scope.IsConsentFormNurseSign || $scope.IsConsentFormAnesthesiaSign || $scope.IsConsentFormDctorSign;
            if (seletedPatientInfo.length == 0 && !Consentsignneed) {
                alertify.error("Please select atleast one patient");
                return false;
            } else {
                console.log("consent need to implement")
            }
            var Type = "bulksignoff" || "";

            let list = [];
            var PreOpNurseChartStatus = "";
            var PreOpAnesthesiaChartStatus = "";
            var IntraOpNurseChartStatus = "";
            var IntraOpAnesthesiaChartStatus = "";
            var PostOpNurseChartStatus = "";
            var PostOpAnesthesiaChartStatus = "";
            var R2PostOpNurseChartStatus = "";
            var R2PostOpAnesthesiaChartStatus = "";
            var FaceSheetChartStatus = "";
            var OperativeChartStatus = "";
            var DischargeChartStatus = "";
            /* LasikPreopChartStatus / LasikIntraopChartStatus / LasikPostopChartStatus,
               filled only for the phases actually being signed */
            var LasikChartStatus = {};
            seletedPatientInfo = seletedPatientInfo || [];
            var UserType = "";
            if ($scope.RoleId == 8) {  //nurse
                UserType = "Nurse";
            }
            if ($scope.RoleId == 38) {  //ASC technician - signs LASIK phases as a nurse
                UserType = "Nurse";
            }
            if ($scope.RoleId == 25 || $scope.RoleId == 30) {  //Anestiea
                UserType = "Anesthesia";
            }
            if ($scope.RoleId == 43 || $scope.RoleId == 1) {  //Doctor
                UserType = "Surgeon";
            }

            let obj = {
                "Screen": "bulksignoff",
                "Type": Type,
                "UserType": UserType,
                "allUserList": angular.copy($scope.allUserList),
                "screenlist": list || "",
                "AppointmentId": $scope.selectedPatientobj.AppointmentID || 0,
                IsshowBulkSignrefreshButton: $scope.IsshowBulkSignrefreshButton || false,
                ConsentformSignatureIndication: $scope.ConsentformSignatureIndication || '',
                /* a LASIK phase is signed by a nurse or an ASC technician, so the
                   password popup offers both roles rather than nurses alone */
                "IsLasikSignOff": false,
                "IsConsentFormNurseSign ": $scope.IsConsentFormNurseSign || false,
                "IsConsentFormAnesthesiaSign ": $scope.IsConsentFormAnesthesiaSign || false,
                "IsConsentFormDctorSign ": $scope.IsConsentFormDctorSign || false,
            };
            if (seletedPatientInfo.length > 0) {
                if (seletedPatientInfo[0].NursePreop && $scope.RoleId == 8 && seletedPatientInfo[0].PreOpNurseChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "NursePreop",
                        "Screen": "PreOp",
                        "UserType": "Nurse",
                        "isasctive": seletedPatientInfo[0].NursePreop,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    PreOpNurseChartStatus = "E";
                }
                if (seletedPatientInfo[0].NurseIntraop && $scope.RoleId == 8 && seletedPatientInfo[0].IntraOpNurseChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "NurseIntraop",
                        "Screen": "IntraOp",
                        "UserType": "Nurse",
                        "isasctive": seletedPatientInfo[0].NurseIntraop,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    IntraOpNurseChartStatus = "E";
                }
                if (seletedPatientInfo[0].NursePostop && $scope.RoleId == 8 && seletedPatientInfo[0].PostOpNurseChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "NursePostop",
                        "Screen": "PostOp-R1",
                        "UserType": "Nurse",
                        "isasctive": seletedPatientInfo[0].NursePostop,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    PostOpNurseChartStatus = "E";
                }
                /* One screenlist entry per LASIK phase that is ticked and not yet
                   signed. The phase travels as its TypeId so the save step knows
                   which chart row it belongs to. */
                angular.forEach($scope.LasikSignOffPhases, function (phase) {
                    if (seletedPatientInfo[0][phase.Model] &&
                        $scope.IsLasikSignOffRole() &&
                        seletedPatientInfo[0][phase.Status] != "E") {

                        var surgeryCategoryId =
                            Number(seletedPatientInfo[0].LasikSurgeryCategoryId) || 0;

                        var screenName = phase.Screen;

                        // Category 3 = LASIK
                        // Category 4 = Laser
                        if (surgeryCategoryId === 4) {
                            screenName = phase.Screen.replace("Lasik", "Laser");
                        }

                        list.push({
                            "Type": Type || "",
                            "name": phase.Model,
                            "Screen": screenName,
                            "UserType": "Nurse",
                            "isasctive": seletedPatientInfo[0][phase.Model],
                            "RoleId": $scope.RoleId,
                            /* the phase's own chart row - 1 Pre-Op, 2 Intra-Op, 3 Post-Op */
                            "TypeId": phase.TypeId,
                            "TypeName": phase.TypeName
                        });
                        LasikChartStatus[phase.Status] = "E";
                        obj.IsLasikSignOff = true;
                    }
                });

                if (seletedPatientInfo[0].NursePostopR2 && $scope.RoleId == 8 && seletedPatientInfo[0].R2PostOpNurseChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "NursePostop",
                        "Screen": "PostOp-R2",
                        "UserType": "Nurse",
                        "isasctive": seletedPatientInfo[0].NursePostopR2,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    R2PostOpNurseChartStatus = "E";
                }
                //if (seletedPatientInfo[0].NursePostop && $scope.RoleId == 8 && seletedPatientInfo[0].PostOpAnesthesiaChartStatus != "E") { //this is for post op recovery2 need to change chartstatusname when all stabilised
                //    let obj = {
                //        "Type": Type || "",
                //        "name": "NursePostop",
                //        "Screen": "PostOp-R2",
                //        "UserType": "Nurse",
                //        "isasctive": seletedPatientInfo[0].NursePostop,
                //        "RoleId": $scope.RoleId
                //    }
                //    list.push(obj);
                //    PostOpNurseChartStatus = "E";
                //}
                if (seletedPatientInfo[0].AnesthesiaPreop && ($scope.RoleId == 25 || $scope.RoleId == 30) && seletedPatientInfo[0].PreOpAnesthesiaChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "AnesthesiaPreop",
                        "Screen": "PreOp",
                        "UserType": "Anesthesia",
                        "isasctive": seletedPatientInfo[0].AnesthesiaPreop,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    PreOpAnesthesiaChartStatus = "E";
                }
                if (seletedPatientInfo[0].AnesthesiaIntraop && ($scope.RoleId == 25 || $scope.RoleId == 30) && seletedPatientInfo[0].IntraOpAnesthesiaChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "AnesthesiaIntraop",
                        "Screen": "IntraOp",
                        "UserType": "Anesthesia",
                        "isasctive": seletedPatientInfo[0].AnesthesiaIntraop,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    IntraOpAnesthesiaChartStatus = "E";
                }
                if (seletedPatientInfo[0].AnesthesiaPostop && ($scope.RoleId == 25 || $scope.RoleId == 30) && seletedPatientInfo[0].PostOpAnesthesiaChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "AnesthesiaPostop",
                        "Screen": "PostOp-R1",
                        "UserType": "Anesthesia",
                        "isasctive": seletedPatientInfo[0].AnesthesiaPostop,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    PostOpAnesthesiaChartStatus = "E";
                }
                if (seletedPatientInfo[0].AnesthesiaPostopR2 && ($scope.RoleId == 25 || $scope.RoleId == 30) && seletedPatientInfo[0].R2PostOpAnesthesiaChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "AnesthesiaPostop",
                        "Screen": "PostOp-R2",
                        "UserType": "Anesthesia",
                        "isasctive": seletedPatientInfo[0].AnesthesiaPostopR2,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    R2PostOpAnesthesiaChartStatus = "E";
                }
                //if (($scope.cacheStorageItem.DoctorID != $scope.UserId) && ($scope.RoleId == 43 || $scope.RoleId == 1 )) {
                //    alertify.error("Appointment Doctor only Have Sigining Access");
                //    return false;
                //}
                if (seletedPatientInfo[0].DoctorNotes && ($scope.RoleId == 43 || $scope.RoleId == 1 || $scope.RoleId == 8) && seletedPatientInfo[0].FaceSheetChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "Facesheet",
                        "Screen": "Facesheet",
                        "UserType": $scope.RoleId == 8 ? 'Nurse' : "Surgeon",
                        "isasctive": seletedPatientInfo[0].DoctorNotes,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    FaceSheetChartStatus = "E";
                }
                if (seletedPatientInfo[0].OperativeNotes && ($scope.RoleId == 43 || $scope.RoleId == 1) && seletedPatientInfo[0].OperativeChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "OperativeNotes",
                        "Screen": "OperativeNotes",
                        "UserType": "Surgeon",
                        "isasctive": seletedPatientInfo[0].OperativeNotes,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    OperativeChartStatus = "E";
                }
                if (seletedPatientInfo[0].DischareSummary && ($scope.RoleId == 43 || $scope.RoleId == 1 || $scope.RoleId == 8) && seletedPatientInfo[0].DischargeChartStatus != "E") {
                    let obj = {
                        "Type": Type || "",
                        "name": "Discharge",
                        "Screen": "Discharge",
                        "UserType": $scope.RoleId == 8 ? 'Nurse' : "Surgeon",
                        "isasctive": seletedPatientInfo[0].DischareSummary,
                        "RoleId": $scope.RoleId
                    }
                    list.push(obj);
                    DischargeChartStatus = "E";
                }

                // Add parameters only if they're not empty

                if ($scope.RoleId == 8) {
                    if (PreOpNurseChartStatus !== "") {
                        obj["PreOpNurseChartStatus"] = PreOpNurseChartStatus;
                    }

                    if (IntraOpNurseChartStatus !== "") {
                        obj["IntraOpNurseChartStatus"] = IntraOpNurseChartStatus;
                    }

                    if (PostOpNurseChartStatus !== "") {
                        obj["PostOpNurseChartStatus"] = PostOpNurseChartStatus;
                    }
                    if (R2PostOpNurseChartStatus !== "") {
                        obj["R2PostOpNurseChartStatus"] = R2PostOpNurseChartStatus;
                    }
                }


                if ($scope.RoleId == 25 || $scope.RoleId == 30) {
                    if (PreOpAnesthesiaChartStatus !== "") {
                        obj["PreOpAnesthesiaChartStatus"] = PreOpAnesthesiaChartStatus;
                    }

                    if (IntraOpAnesthesiaChartStatus !== "") {
                        obj["IntraOpAnesthesiaChartStatus"] = IntraOpAnesthesiaChartStatus;
                    }

                    if (PostOpAnesthesiaChartStatus !== "") {
                        obj["PostOpAnesthesiaChartStatus"] = PostOpAnesthesiaChartStatus;
                    }
                    if (R2PostOpAnesthesiaChartStatus !== "") {
                        obj["R2PostOpAnesthesiaChartStatus"] = R2PostOpAnesthesiaChartStatus;
                    }
                }

                if ($scope.RoleId == 43 || $scope.RoleId == 1) {  //surgion
                    if (FaceSheetChartStatus !== "") {
                        obj["FaceSheetChartStatus"] = FaceSheetChartStatus;
                    }
                    if (OperativeChartStatus !== "") {
                        obj["OperativeChartStatus"] = OperativeChartStatus;
                    }

                    if (DischargeChartStatus !== "") {
                        obj["DischargeChartStatus"] = DischargeChartStatus;
                    }
                }
                if ($scope.RoleId == 8) {
                    if (DischargeChartStatus !== "") {
                        obj["DischargeChartStatus"] = DischargeChartStatus;
                    }
                    if (FaceSheetChartStatus !== "") {
                        obj["FaceSheetChartStatus"] = FaceSheetChartStatus;
                    }
                }

                /* LASIK phases, nurse or ASC technician */
                if ($scope.IsLasikSignOffRole()) {
                    angular.forEach(LasikChartStatus, function (status, key) {
                        obj[key] = status;
                    });
                }
            }



            $scope.signmodalInstance = $uibModal.open({
                "templateUrl": "templates/consultation/SignOffPasswordNew.html",
                "controller": "UsSignOffPasswordPopupCtrl",
                "size": "md",
                "backdrop": "static",
                "keyboard": false,
                "resolve": {
                    "obj": function () { return obj; }
                },
                "windowClass": "",
            });
            $scope.signmodalInstance.result.then(function (result) {
                console.log("Modal closed with result:", result);
                let bulkDoctorID = result.DoctorId || 0;
                let signofflist = result.screenlist || [];
                if ($scope.AscAppointmentsList.length > 0) {
                    let filterapptobj = $filter('filter')($scope.AscAppointmentsList, { 'AppointmentID': $scope.selectedPatientobj.AppointmentID }, true)[0] || [];
                    if (filterapptobj != undefined) {
                        $scope.selectedPatientSignOff(filterapptobj, filterapptobj.SignoffsubtabId);
                    }
                }
                if ($scope.IsConsentFormNurseSign || $scope.IsConsentFormAnesthesiaSign || $scope.IsConsentFormDctorSign) {
                    const NURSE_ROLES = [8];
                    const DOCTOR_ROLES = [1, 43];
                    const ANESTHESIA_ROLES = [25, 30];
                    $scope.ProviderSigBase64 = null;
                    $scope.ConsentAnesthesistEncryptedSig = null;
                    $scope.NurseSigBase64 = null;
                    let signingUserArr = $filter('filter')($scope.allUserList, { 'DoctorID': bulkDoctorID }, true) || [];
                    let signingUser = signingUserArr.length > 0 ? signingUserArr[0] : null;
                    if (signingUser) {
                        let roleId = signingUser.RoleId;

                        if (NURSE_ROLES.indexOf(roleId) > -1) {
                            // bind nurse signature wherever your nurse-sign code path reads it
                            $scope.NurseSigBase64 = signingUser.SignatureOfUser || null;
                            $scope.ConsentNurseId = bulkDoctorID;

                        }
                        if (DOCTOR_ROLES.indexOf(roleId) > -1) {
                            $scope.Isbulksignofdone = true; // gate used in injectSignaturesIntoHtml
                            $scope.ProviderSigBase64 = signingUser.SignatureOfUser || null;
                            $scope.AppointmentDoctorId = bulkDoctorID;
                        }

                        if (ANESTHESIA_ROLES.indexOf(roleId) > -1) {
                            $scope.IsAnesthesiabulksignofdone = true; // gate used in injectSignaturesIntoHtml
                            $scope.ConsentAnesthesistEncryptedSig = signingUser.SignatureOfUser || null;
                            $scope.ConsentAnesthesiaId = bulkDoctorID;
                        }
                    }
                    if ($scope.IsshowBulkSignrefreshButton) {
                        if ($scope.IsConsentFormNurseSign && ($scope.RoleId == 8)) {
                            $scope.bulkSignAllConsents();
                        } else if ($scope.IsConsentFormAnesthesiaSign && ($scope.RoleId == 25 || $scope.RoleId == 30)) {
                            $scope.bulkSignAllConsents();
                        } else if ($scope.IsConsentFormDctorSign && ($scope.RoleId == 1 || $scope.RoleId == 43)) {
                            $scope.bulkSignAllConsents();
                        }
                    }

                }
                $scope.Refreshappt();

                let givenByUser = '';

                $scope.LogObj.LogArray = [];

                var NursePreopItem = $filter("filter")(signofflist, function (Fitem) {
                    return Fitem.name === "NursePreop";
                });
                var NurseIntraopItem = $filter("filter")(signofflist, function (Oitem) {
                    return Oitem.name === "NurseIntraop";
                });
                var NursePostopItem = $filter("filter")(signofflist, function (Ditem) {
                    return Ditem.name === "NursePostop";
                });
                var AnesthesiaPreopItem = $filter("filter")(signofflist, function (Fitem) {
                    return Fitem.name === "AnesthesiaPreop";
                });
                var AnesthesiaIntraopItem = $filter("filter")(signofflist, function (Oitem) {
                    return Oitem.name === "AnesthesiaIntraop";
                });
                var AnesthesiaPostopItem = $filter("filter")(signofflist, function (Ditem) {
                    return Ditem.name === "AnesthesiaPostop";
                });
                var facesheetItem = $filter("filter")(signofflist, function (Fitem) {
                    return Fitem.name === "Facesheet";
                });
                var OperativeItem = $filter("filter")(signofflist, function (Oitem) {
                    return Oitem.name === "OperativeNotes";
                });
                var DischargeItem = $filter("filter")(signofflist, function (Ditem) {
                    return Ditem.name === "Discharge";
                });

                var ReviewedByArraylist = $filter("filter")($scope.allUserList, function (item) {
                    return item.DoctorID == bulkDoctorID;
                });

                if (ReviewedByArraylist.length > 0) {
                    givenByUser = angular.copy(ReviewedByArraylist[0].SecondUserFullName) +
                        (ReviewedByArraylist[0].LicenseNumber ? " Lic:" + angular.copy(ReviewedByArraylist[0].LicenseNumber) : "");
                }


                let selectedScreens = [];
                let subModuleId = 0;

                if (NursePreopItem && NursePreopItem.length > 0) {
                    selectedScreens.push("Nurse Preop");
                    subModuleId = 9;
                }
                if (NurseIntraopItem && NurseIntraopItem.length > 0) {
                    selectedScreens.push("Nurse Intraop");
                    if (subModuleId === 0) subModuleId = 10;
                }
                if (NursePostopItem && NursePostopItem.length > 0) {
                    selectedScreens.push("Nurse Postop");
                    if (subModuleId === 0) subModuleId = 11;
                }
                if (AnesthesiaPreopItem && AnesthesiaPreopItem.length > 0) {
                    selectedScreens.push("Anesthesia Preop");
                    if (subModuleId === 0) subModuleId = 9;
                }
                if (AnesthesiaIntraopItem && AnesthesiaIntraopItem.length > 0) {
                    selectedScreens.push("Anesthesia Intraop");
                    if (subModuleId === 0) subModuleId = 10;
                }
                if (AnesthesiaPostopItem && AnesthesiaPostopItem.length > 0) {
                    selectedScreens.push("Anesthesia Postop");
                    if (subModuleId === 0) subModuleId = 11;
                }
                if (facesheetItem && facesheetItem.length > 0) {
                    selectedScreens.push("Facesheet");
                    if (subModuleId === 0) subModuleId = 3;
                }
                if (OperativeItem && OperativeItem.length > 0) {
                    selectedScreens.push("Operative Notes");
                    if (subModuleId === 0) subModuleId = 5;
                }
                if (DischargeItem && DischargeItem.length > 0) {
                    selectedScreens.push("Discharge");
                    if (subModuleId === 0) subModuleId = 4;
                }

                let screenTypeValue = selectedScreens.join(", ");

                if (selectedScreens.length > 0) {
                    let obj = {
                        "LogId": 0,
                        "ModuleId": 2,
                        "ModuleName": "ASC",
                        "SubModuleId": subModuleId,
                        "SubModuleName": "Bulksignoff ",
                        "ScreenType": screenTypeValue,
                        "ActionType": "Signed off",
                        "OldActionDescription": '',
                        "NewActionDescription": `Signed by ${givenByUser} (${screenTypeValue})`,
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                    };

                    $scope.LogObj.LogArray.push(obj);
                    $scope.AddAuditLog($scope.LogObj);
                }

            }, function (reason) {
                console.log("Modal dismissed:", reason);
            });
        }
        if (TabNo == 2) {
            // filtering the user list based on the role 
            let allowedRoles = [];
            let checkSuffix = false;
            if ($scope.RoleId === 43 || $scope.RoleId === 1) {
                allowedRoles = [43, 1];
                checkSuffix = true;
            } else if ($scope.RoleId === 25 || $scope.RoleId === 30) {
                allowedRoles = [30];
            }

            $scope.ordersignoffObj.OrdersSignOffUserList = $filter('filter')($scope.allUserList, function (user) {
                return allowedRoles.includes(user.RoleId) && (!checkSuffix || user.SuffixId === 10);
            });
            $scope.ordersignoffObj.ReviewedBy = $scope.UserId || 0;
            $scope.ordersignoffObj.ReviewedByPassword = '';
            if ($scope.AllOrdersPatientList.length > 0) {
                let GrennFlag = true;
                $scope.AllOrdersPatientList.forEach(signoffitem => {
                    if (signoffitem.AnesthesiaPreop || signoffitem.AnesthesiaIntraop || signoffitem.AnesthesiaPostop || signoffitem.PreOpOrders || signoffitem.IntraOpOrders || signoffitem.PostopOrders) {
                        GrennFlag = false;
                    }
                });
                if (GrennFlag) {
                    alertify.error("Please select Atleast One Patient Orders");
                    return false;
                }
            } else {
                alertify.error("Please select Atleast One Patient Orders");
                return false;
            }

            $scope.signmodalOrderInstance = $uibModal.open({
                "templateUrl": "UsbulksignoffOrders.html",
                "size": "md",
                "backdrop": "static",
                "keyboard": false,
                "scope": $scope,
                "windowClass": "",
                "controller": function ($scope, $uibModal, $uibModalInstance) {
                    $scope.uibclose = function () {
                        $uibModalInstance.dismiss("cancel");
                    };
                }
            });
            $scope.signmodalOrderInstance.result.then(function (result) {
                console.log("Modal closed with result:", result);
            }, function (reason) {
                console.log("Modal dismissed:", reason);
            });

        }
    }
    $scope.bulkSignAllConsents = function () {
        var allConsents = $scope.consentsMainObj.MainConsents || [];

        var toSign = allConsents.filter(function (c) {
            var matchesAny = false;

            if ($scope.IsConsentFormNurseSign) {
                if (c.IsStaffSignRequired === true && c.IsStaffSignatureDone === false) {
                    matchesAny = true;
                }
            }

            if ($scope.IsConsentFormDctorSign) {
                if (c.IsDoctorSignRequired === true && c.IsProviderSignatureDone === false) {
                    matchesAny = true;
                }
            }

            if ($scope.IsConsentFormAnesthesiaSign) {
                if (c.IsAnesthesistSignRequired === true && c.IsAnesthesistSignatureDone === false) {
                    matchesAny = true;
                }
            }

            // Fallback to legacy flag if none of the role flags are set
            //// (keeps old behavior for callers that don't set role flags, e.g. bulkSignAllConsents)
            //if (!$scope.IsConsentFormNurseSign && !$scope.IsConsentFormDctorSign && !$scope.IsConsentFormAnesthesiaSign) {
            //    matchesAny = c.CanBulksignconsent === true;
            //}

            return matchesAny;
        });

        if (toSign.length === 0) {
            alertify.error("No consents require doctor signature, or all already signed.");
            return;
        }


        var providerSigBase64 = $scope.ProviderSigBase64 || null;


        _sendBulkSignRequest(toSign, providerSigBase64);

    };
    function injectSignaturesIntoHtml(htmlContent, providerSigBase64, signedDateTime, citem) {
        if (!htmlContent) return '';

        // Build the same img tag that genProviderImg() renders into the DOM
        if ($scope.Isbulksignofdone && providerSigBase64 && (citem.IsDoctorSignRequired && !citem.IsProviderSignatureDone)) {

            var sigImgHtml = '<table style="border:none;"><tbody><tr><td>'
                + '<img src="' + providerSigBase64 + '" '
                + 'style="max-width:200px;max-height:80px;display:block;" />'
                + '</td></tr></tbody></table>';

            htmlContent = htmlContent.replace(/##ProviderSignature##/gi, sigImgHtml);
            htmlContent = htmlContent.replace(/##ProviderSignedDateTime##/gi, signedDateTime);

            htmlContent = htmlContent.replace(/##ProviderSignature##/gi, '');
            htmlContent = htmlContent.replace(/##ProviderSignedDateTime##/gi, '');
        }

        if ($scope.IsAnesthesiabulksignofdone && $scope.ConsentAnesthesistEncryptedSig && (citem.IsAnesthesistSignRequired && !citem.IsAnesthesistSignatureDone)) {

            var anesthesistSigImgHtml =
                '<table style="border:none;"><tbody><tr><td>'
                + '<img src="' + $scope.ConsentAnesthesistEncryptedSig + '" '
                + 'style="max-width:200px;max-height:80px;display:block;" />'
                + '</td></tr></tbody></table>';

            htmlContent = htmlContent.replace(/##AnesthesistSignature##/gi, anesthesistSigImgHtml);
            htmlContent = htmlContent.replace(/##AnesthesistSignDateTime##/gi, signedDateTime || '');

            htmlContent = htmlContent.replace(/##AnesthesistSignature##/gi, '');
            htmlContent = htmlContent.replace(/##AnesthesistSignDateTime##/gi, '');
        }

        // *** NEW: Nurse signature injection ***
        if ($scope.IsConsentFormNurseSign && $scope.NurseSigBase64 && (citem.IsStaffSignRequired && !citem.IsStaffSignatureDone)) {

            var nurseSigImgHtml =
                '<table style="border:none;"><tbody><tr><td>'
                + '<img src="' + $scope.NurseSigBase64 + '" '
                + 'style="max-width:200px;max-height:80px;display:block;" />'
                + '</td></tr></tbody></table>';

            htmlContent = htmlContent.replace(/##StaffSignature##/gi, nurseSigImgHtml);
            htmlContent = htmlContent.replace(/##StaffSignDateTime##/gi, signedDateTime || '');

            htmlContent = htmlContent.replace(/##StaffSignature##/gi, '');
            htmlContent = htmlContent.replace(/##StaffSignDateTime##/gi, '');
        }

        return htmlContent;
    }

    function _sendBulkSignRequest(toSign, providerSigBase64) {
        var signedDateTime = null, signedDateTimeForDB = null;
        if ($scope.admissiondatetime) {
            signedDateTime = $filter('date')($scope.admissiondatetime, "MM-dd-yyyy hh:mm a");
            signedDateTimeForDB = $filter('date')($scope.admissiondatetime, "yyyy-MM-dd HH:mm:ss");
        } else {
            signedDateTime = moment(new Date()).format("MM-DD-YYYY hh:mm A");
            signedDateTimeForDB = moment(new Date()).format("YYYY-MM-DD HH:mm:ss");
        }
        var cApptDate = $filter('date')(new Date(), "yyyy-MM-dd");

        var reqList = toSign.map(function (c) {
            var originalHTML = c.HTMLContent || c.PDFcontent || "";

            var processedHtml = injectSignaturesIntoHtml(
                originalHTML,
                $scope.ProviderSigBase64,
                signedDateTime, c
            );

            var H = USPrintService.HeaderHelpers;
            var cfg = H.extractHeaderConfig(originalHTML || '') || null;
            var consentName = c.ConsentFormName || c.DocumentName || '';

            if (($scope.Isbulksignofdone) && (providerSigBase64) && (c.IsDoctorSignRequired && !c.IsProviderSignatureDone)) {
                c.ProviderSignedDateTime = signedDateTimeForDB || null;
                c.IsProviderSignatureDone = true;
                c.ProviderUserId = $scope.AppointmentDoctorId || 0;
                c.ProviderSignCaptureUserId = $scope.AppointmentDoctorId || 0;
                c.providerSigBase64 = $scope.ProviderSigBase64 || null;
            }

            if ($scope.ConsentAnesthesistEncryptedSig && (c.IsAnesthesistSignRequired && !c.IsAnesthesistSignatureDone)) {
                c.AnesthesistSignedDateTime = signedDateTimeForDB || null;
                c.IsAnesthesistSignatureDone = true;
                c.AnesthesistUserId = $scope.ConsentAnesthesiaId || 0;
                c.AnesthesistSignCaptureUserId = $scope.ConsentAnesthesiaId || 0;
                c.AnesthesistEncryptedSig = $scope.ConsentAnesthesistEncryptedSig || null;
            }

            // *** NEW: Nurse — populate staff sign fields ***
            if ($scope.NurseSigBase64 && (c.IsStaffSignRequired && !c.IsStaffSignatureDone)) {
                c.StaffSignedDateTime = signedDateTimeForDB || null;
                c.IsStaffSignatureDone = true;
                c.StaffUserId = $scope.ConsentNurseId || 0;
                c.StaffSignCaptureUserId = $scope.ConsentNurseId || 0;
                c.StaffEncryptedSig = $scope.NurseSigBase64 || null;
            }

            return {
                "UserId": $scope.UserId,
                "HospitalId": $scope.HospitalId,
                "ConsentTemplateId": c.ConsentTemplateId || 0,
                "PatientConsentDocumentId": c.PatientConsentDocumentId || 0,
                "PatientId": $scope.selectedPatientobj.PatientID,
                "VisitId": $scope.selectedPatientobj.VisitId || 0,
                "PatientName": $scope.cacheStorageItem.PatientName,
                "AppointmentId": $scope.selectedPatientobj.AppointmentID,
                "AppointmentDate": $scope.selectedPatientobj.ConsultationDt || null,
                "ConsentFormId": c.ConsentFormId || 0,
                "S3URL": c.S3URL || "",
                "Base64": "",
                "DocumentExt": "pdf",
                "DocumentName": c.DocumentName || "",
                "DisplayName": consentName,

                "IsPatientSignatureDone": c.IsPatientSignatureDone || false,
                "IsStaffSignatureDone": c.IsStaffSignatureDone || false,
                "StaffUserId": c.StaffUserId || 0,
                "IsCounselorSignatureDone": c.IsCounselorSignatureDone || false,
                "CounselorUserId": c.CounselorUserId || 0,
                "IsAnesthesistSignatureDone": c.IsAnesthesistSignatureDone || false,
                "AnesthesistUserId": c.AnesthesistUserId || 0,
                "IsGaurdianSignatureDone": c.IsGaurdianSignatureDone || false,
                "GaurdianUserId": c.GaurdianUserId || 0,
                "GaurdianFirstName": c.GaurdianFirstName || "",
                "GaurdianLastName": c.GaurdianLastName || "",
                "GaurdianRelationShipId": c.GaurdianRelationShipId || null,

                "IsProviderSignatureDone": c.IsProviderSignatureDone || false,
                "ProviderUserId": c.ProviderUserId,
                "ProviderSignedDateTime": c.ProviderSignedDateTime,
                "ProviderSignCaptureUserId": c.ProviderSignCaptureUserId,

                "PatientSignedDateTime": c.PatientSignedDateTime || null,
                "StaffSignedDateTime": c.StaffSignedDateTime || null,
                "CounselorSignedDateTime": c.CounselorSignedDateTime || null,
                "AnesthesistSignedDateTime": c.AnesthesistSignedDateTime || null,
                "GaurdianSignedDateTime": c.GaurdianSignedDateTime || null,

                "PatientSignCaptureUserId": c.PatientSignCaptureUserId || 0,
                "StaffSignCaptureUserId": c.StaffSignCaptureUserId || 0,
                "CounselorSignCaptureUserId": c.CounselorSignCaptureUserId || 0,
                "AnesthesistSignCaptureUserId": c.AnesthesistSignCaptureUserId || 0,
                "GaurdianSignCaptureUserId": c.GaurdianSignCaptureUserId || 0,

                "PatientEncryptedSig": c.PatientEncryptedSig || "",
                "DoctorEncryptedSig": c.providerSigBase64,
                "StaffEncryptedSig": c.StaffEncryptedSig || "",
                "CounselorEncryptedSig": c.CounselorEncryptedSig || "",
                "AnesthesistEncryptedSig": c.AnesthesistEncryptedSig || "",
                "GuardianEncryptedSig": c.GuardianEncryptedSig || "",
                "PatientIntialEncryptedSig": c.PatientIntialEncryptedSig || "",

                "IsPartiallySaved": false,
                "IsScannedDocument": false,
                "HTMLContent": processedHtml,
                "HeaderText": consentName,
                "HeaderCfg": cfg,
                "OldPatientConsentFormId": 0,
                "Logs": {}
            };
        });

        eHnoteSettingsDataService.AddUpdateBulkPatientSignedConsentDocuments(reqList)
            .then(function (resp) {
                var r = resp.data;
                if (r.Status === 'Success') {
                    alertify.success("All " + r.SuccessCount + " consent(s) signed successfully.");
                } else {
                    alertify.error(r.SuccessCount + " signed. " + r.FailedCount + " failed. Check logs.");
                    console.error("Bulk sign failures:", r.FailedDetails);
                }
                $scope.GetPatientAppointmentConsentsById();
            }, function (err) {
                alertify.error("Bulk sign request failed. Please try again.");
                console.error(err);
            });
    }

