    function loadallOrdersAllPatientsList() {
        let consultationDt = $filter('date')($scope.SearchObj.ConsultationDt, "yyyy-MM-dd");
        //let Locationids = $scope.SearchObj.Locationids || 0;
        let newlist8 = "";
        for (var i in $scope.MultiselectDoctorlist) {
            if ($scope.MultiselectDoctorlist[i].isChecked) {
                newlist8 += "," + $scope.MultiselectDoctorlist[i].DoctorID;
            }
        }
        if (newlist8.charAt(0) === ",") {
            newlist8 = newlist8.slice(1);
        }
        var Locationids = '';
        if ($scope.GetAllIndicatorForFacility == 1 || $scope.AppListselectedclinic.ClinicId === 0) {
            var TempAppListdoctoraddress = $filter("filter")($scope.AppListdoctoraddress, function (iterator, ind) { return iterator.ClinicId !== 0; });
            Locationids = _.pluck(TempAppListdoctoraddress, "ClinicId").join(",");
        } else {
            Locationids = $scope.AppListselectedclinic.ClinicId;
        }

        let newlist2 = "";
        for (var i in $scope.Visitreasons) {
            if ($scope.Visitreasons[i].isChecked) {
                /*newlist2 += "," + $scope.Visitreasons[i].ReasonId;*/
                newlist2 += "," + $scope.Visitreasons[i].ParentAppointmentVisitReasonId;
            }
        }
        if (newlist2.charAt(0) === ",") {
            newlist2 = newlist2.slice(1);
        }

        let obj = {
            "ConsultationDt": $scope.SearchObj.ConsultationDt || "",
            "HospitalID": $scope.HospitalId || 0,
            "Locationids": Locationids || 0,
            "UserId": $scope.UserId || 0,
            "DoctorIds": newlist8,
            "VisitReasonIdList": newlist2,
            "SurgeryCategoryIds": $scope.SearchObj.SurgeryCategoryIds,
        }
        eHnoteSurgeryService.GetAllOrdersAllascPatientsList(obj).then(function (resp) {
            if (resp.data.status == "Success") {
                $scope.AllOrdersPatientList = resp.data.AppointmentList || [];
                if ($scope.AllOrdersPatientList.length > 0) {
                    angular.forEach($scope.AllOrdersPatientList, function (orderitem) {
                        if (orderitem.PreopOrderDetails.length > 0) {
                            let PreopOrderSurgionDetails = orderitem.PreopOrderDetails.filter(preopitem => preopitem.MedTypeId == 2);
                            if (PreopOrderSurgionDetails.length > 0) {
                                orderitem.PreOpOrders= orderitem.PreopDoctorIsOrderReviewed = (PreopOrderSurgionDetails.every(preopitem => preopitem.IsOrderReviewed === true));
                            } else {
                                orderitem.PreOpOrders = false;
                                orderitem.PreopDoctorIsOrderReviewed = true;
                            }
                            let PreopOrderAnestiaDetails = orderitem.PreopOrderDetails.filter(preopitem => preopitem.MedTypeId == 1);
                            if (PreopOrderAnestiaDetails.length > 0) {
                                orderitem.AnesthesiaPreop = orderitem.PreopAnesthesiaIsOrderReviewed = PreopOrderAnestiaDetails.every(preopitem => preopitem.IsOrderReviewed === true);
                            } else {
                                orderitem.AnesthesiaPreop = false;
                                orderitem.PreopAnesthesiaIsOrderReviewed = true;
                            }
                        }
                        else {
                            orderitem.PreOpOrders = false;
                            orderitem.AnesthesiaPreop = false;
                            orderitem.PreopDoctorIsOrderReviewed =  true;
                            orderitem.PreopAnesthesiaIsOrderReviewed =  true;
                        }
                        if (orderitem.IntraOpOrderDetails.length > 0) {
                            let IntraOpOrderSurgionDetails = orderitem.IntraOpOrderDetails.filter(intraopitem => intraopitem.MedTypeId == 4);
                            if (IntraOpOrderSurgionDetails.length > 0) {
                                orderitem.IntraOpOrders = orderitem.IntraOpDoctorIsOrderReviewed= (IntraOpOrderSurgionDetails.every(intraopitem => intraopitem.IsOrderReviewed === true));
                            } else {
                                orderitem.IntraOpOrders = false;
                                orderitem.IntraOpDoctorIsOrderReviewed = true;
                            }

                            let IntraOpOrderAnestiaDetails = orderitem.IntraOpOrderDetails.filter(intraopitem => intraopitem.MedTypeId == 3);
                            if (IntraOpOrderAnestiaDetails.length > 0) {
                                orderitem.AnesthesiaIntraop = orderitem.IntraOpAnesthesiaIsOrderReviewed = IntraOpOrderAnestiaDetails.every(intraopitem => intraopitem.IsOrderReviewed === true);
                            } else {
                                orderitem.AnesthesiaIntraop = false;
                                orderitem.IntraOpAnesthesiaIsOrderReviewed = true;
                            }
                        }
                        else {
                            orderitem.AnesthesiaIntraop = false;
                            orderitem.IntraOpOrders = false;
                            orderitem.IntraOpDoctorIsOrderReviewed =  true;
                            orderitem.IntraOpAnesthesiaIsOrderReviewed =  true;
                        }
                        if (orderitem.PostOpOrderDetails.length > 0) {
                            let PostOpOrderSurgionDetails = orderitem.PostOpOrderDetails.filter(postopitem => postopitem.MedTypeId == 5);
                            if (PostOpOrderSurgionDetails.length > 0) {
                                orderitem.PostopOrders = orderitem.PostOpOpDoctorIsOrderReviewed= (PostOpOrderSurgionDetails.every(postopitem => postopitem.IsOrderReviewed === true));
                            } else {
                                orderitem.PostopOrders = false;
                                orderitem.PostOpOpDoctorIsOrderReviewed = true;
                            }

                            let PostOpOpOrderAnestiaDetails = orderitem.PostOpOrderDetails.filter(postopitem => postopitem.MedTypeId == 8);
                            if (PostOpOpOrderAnestiaDetails.length > 0) {
                                orderitem.AnesthesiaPostop = orderitem.PostOpOpAnesthesiaIsOrderReviewed= PostOpOpOrderAnestiaDetails.every(postopitem => postopitem.IsOrderReviewed === true);
                            } else {
                                orderitem.AnesthesiaPostop = false;
                                orderitem.PostOpOpAnesthesiaIsOrderReviewed = true;
                            }
                        }
                        else {
                            orderitem.PostopOrders = false;
                            orderitem.AnesthesiaPostop = false;
                            orderitem.PostOpOpDoctorIsOrderReviewed =  true;
                            orderitem.PostOpOpAnesthesiaIsOrderReviewed = true;
                        }
                    });
                    let selectedPatientObj = $scope.AllOrdersPatientList.find(item => item.Patient.PatientID === $scope.selectedPatientobj.PatientID);
                    selectedPatientObj = selectedPatientObj || '';
                    if (selectedPatientObj != '') {
                        $scope.selectedPatient(selectedPatientObj, 2);
                    } else {
                        $scope.selectedPatient($scope.AllOrdersPatientList[0], 2);
                    }

                }
                $scope.MainAllOrdersPatientList = angular.copy($scope.AllOrdersPatientList)||[];
            }
        });

    };

